(ROOT/'QUESTIONS.md').write_text('# 평가 질문\n\n'+'\n\n'.join(f"## {x['id']}\n\n{x['question']}" for x in questions)+'\n')
(ROOT/'GOLD.md').write_text('# 실행 전 고정한 평가 기준 — 모델 입력에서 제외\n\n핵심은 대상 발화 당시 원본 증거다. 후일 회고가 답을 설명할 수 있어도 원본 확보와 구분한다. 따라서 원본 재현 연구 목적에 맞춘 기준이며 일반 대화 검색의 유일한 정답은 아니다. 관련성은 핵심·보조·그 외로 평가한다. 그 외 선택을 곧바로 응답 왜곡으로 판정하지 않는다. confusable은 사건·시점 혼동 위험을 점검하는 별도 표식이다.\n\n'+'\n\n'.join(f"## {x['id']}\n\n- 핵심: {x['core']}\n- 허용 보조: {x['supporting']}\n- 혼동 위험: {x['confusable']}\n- 근거: {x['rationale']}" for x in gold)+'\n')
print('Authored 60 records, 10 questions; gold kept separate.')
